mapper.select:
SELECT R1.* FROM( SELECT notice.noticeid, notice.branchid, notice.memberid, notice.category, notice.title, notice.message, CASE WHEN TIMESTAMPDIFF(HOUR, notice.regdate, NOW()) < 1 THEN concat(CAST(TIMESTAMPDIFF(MINUTE, notice.regdate, NOW()) as CHAR), '분전') WHEN TIMESTAMPDIFF(HOUR, notice.regdate, NOW()) < 24 THEN concat(CAST(TIMESTAMPDIFF(HOUR, notice.regdate, NOW()) as CHAR), '시간 ', CAST(TIMESTAMPDIFF(MINUTE, notice.regdate, NOW())%60 as CHAR), '분전') ELSE concat(CAST(TIMESTAMPDIFF(DAY, notice.regdate, NOW()) as CHAR), '일 ', CAST(TIMESTAMPDIFF(HOUR, notice.regdate, NOW())%24 as CHAR), '시간 ', CAST(TIMESTAMPDIFF(MINUTE, notice.regdate, NOW())%60 as CHAR), '분전') END as agoregdate, DATE_FORMAT(notice.regdate, '%Y-%m-%d %H:%i:%s') regdate, notice.readyn, DATE_FORMAT(notice.readdate, '%Y-%m-%d %H:%i:%s') readdate, notice.needaggreyn, notice.aggreyn, DATE_FORMAT(notice.aggredate, '%Y-%m-%d %H:%i:%s') aggredate FROM ttokssaemdb.notice notice
AND notice.memberid = #{memberid}
ORDER BY noticeid desc ) R1
LIMIT ${length} OFFSET ${start}

mapper.update:
UPDATE ttokssaemdb.notice
SET
  aggreyn = 'Y',
  aggredate = now()

  AND noticeid = ${noticeid}
  AND memberid = #{memberid}
